1	import { randomUUID } from "node:crypto";
2	import type { SupabaseClient } from "@supabase/supabase-js";
3	
4	// Money moved between the owner's own accounts is a transfer, never income or spending.
5	// Detection is deterministic and IBAN-only: a row's counterparty IBAN is one of the owner's
6	// own accounts. Every decision goes through the audited link RPCs, so each one can be undone.
7	
8	export const MATCH_DAYS = 3;
9	const IBAN = /^[A-Z]{2}[0-9]{2}[A-Z0-9]{8,30}$/;
10	
11	export function normalizeIban(value: string) {
12	  const iban = value.replace(/\s/g, "").toUpperCase();
13	  return IBAN.test(iban) ? iban : null;
14	}
15	
16	/** Every IBAN-shaped value in an original source row (counterparty columns differ per bank). */
17	export function sourceIbans(row: unknown) {
18	  if (!row || typeof row !== "object") return [];
19	  return Object.values(row).flatMap(value => typeof value === "string" ? [normalizeIban(value)].filter((iban): iban is string => Boolean(iban)) : []);
20	}
21	
22	export type TransferCandidate = {
23	  id: string; version: number; accountId: string; postedOn: string; amountMinor: bigint; currencyCode: string;
24	  reviewReasons: string[]; ibans: string[];
25	};
26	export type OwnAccounts = { tracked: Map<string, string>; untracked: Map<string, string> }; // IBAN → account id / identifier id
27	
28	const days = (a: string, b: string) => Math.abs(Date.parse(a) - Date.parse(b)) / 86400000;
29	
30	/** Every posted leg in the workspace, so a lone leg can tell whether its other side exists. */
31	export type Leg = Pick<TransferCandidate, "id" | "accountId" | "postedOn" | "amountMinor" | "currencyCode">;
32	
33	export function findOwnTransfers(rows: TransferCandidate[], own: OwnAccounts, legs: Leg[] = rows) {
34	  // The posting account's own IBAN often appears in its row too; only the other side counts.
35	  const counterparts = (row: TransferCandidate) => row.ibans.filter(iban => own.tracked.get(iban) !== row.accountId);
36	  const points = (row: TransferCandidate, accountId: string) => counterparts(row).some(iban => own.tracked.get(iban) === accountId);
37	  const matches = (out: TransferCandidate, into: TransferCandidate) => out.amountMinor < 0n && into.amountMinor === -out.amountMinor
38	    && out.currencyCode === into.currencyCode && out.accountId !== into.accountId && days(out.postedOn, into.postedOn) <= MATCH_DAYS;
39	  const used = new Set<string>();
40	  const pairs: { outId: string; inId: string }[] = [];
41	  const outs = rows.filter(row => row.amountMinor < 0n), ins = rows.filter(row => row.amountMinor > 0n);
42	  const take = (out: TransferCandidate, into: TransferCandidate) => { used.add(out.id); used.add(into.id); pairs.push({ outId: out.id, inId: into.id }); };
43	
44	  // IBAN-proven pairs first, closest date wins.
45	  for (const out of outs) {
46	    const proven = ins.filter(into => !used.has(into.id) && matches(out, into) && (points(out, into.accountId) || points(into, out.accountId)))
47	      .sort((a, b) => days(out.postedOn, a.postedOn) - days(out.postedOn, b.postedOn) || a.id.localeCompare(b.id));
48	    if (!used.has(out.id) && proven[0]) take(out, proven[0]);
49	  }
50	  // A leg whose other side is missing: the counterparty is an own account, and no opposite
51	  // leg exists in that account within the window. Untracked accounts are named by identifier;
52	  // tracked accounts by IBAN.
53	  const unpaired = (row: TransferCandidate, accountId: string) => !legs.some(other => other.id !== row.id && other.accountId === accountId
54	    && other.currencyCode === row.currencyCode && other.amountMinor === -row.amountMinor && days(row.postedOn, other.postedOn) <= MATCH_DAYS);
55	  const single = rows.flatMap((row): { transactionId: string; identifierId?: string; iban?: string }[] => {
56	    if (used.has(row.id)) return [];
57	    const identifierId = counterparts(row).map(iban => own.untracked.get(iban)).find(Boolean);
58	    if (identifierId) return [{ transactionId: row.id, identifierId }];
59	    const iban = counterparts(row).find(item => own.tracked.has(item));
60	    const accountId = iban ? own.tracked.get(iban) : undefined;
61	    return iban && accountId && unpaired(row, accountId) ? [{ transactionId: row.id, iban }] : [];
62	  });
63	  return { pairs, single };
64	}
65	
66	const PAGE = 1000, MAX_ROWS = 5000;
67	
68	export async function loadOwnAccounts(db: SupabaseClient, workspaceId: string): Promise<OwnAccounts> {
69	  const [identifiers, bank, accounts] = await Promise.all([
70	    db.from("own_account_identifiers").select("id, account_id, iban").eq("workspace_id", workspaceId),
71	    db.from("bank_connection_accounts").select("iban, account_name, currency_code").eq("workspace_id", workspaceId).not("iban", "is", null),
72	    db.from("accounts").select("id, name, currency_code").eq("workspace_id", workspaceId),
73	  ]);
74	  for (const result of [identifiers, bank, accounts]) if (result.error) throw new Error(result.error.message);
75	  const tracked = new Map<string, string>(), untracked = new Map<string, string>();
76	  // A bank sync imports into the account with the bank's name and currency (see bankAccountNames).
77	  for (const row of bank.data ?? []) {
78	    const account = accounts.data?.find(item => item.name === row.account_name && item.currency_code === row.currency_code);
79	    const iban = normalizeIban(row.iban ?? "");
80	    if (account && iban) tracked.set(iban, account.id);
81	  }
82	  for (const row of identifiers.data ?? []) {
83	    if (row.account_id) tracked.set(row.iban, row.account_id); else untracked.set(row.iban, row.id);
84	  }
85	  return { tracked, untracked };
86	}
87	
88	type Row = { id: string; version: number; account_id: string; posted_on: string; amount_minor: string; currency_code: string; review_reasons: string[] | null;
89	  transaction_sources: { source_transactions: { original_row: unknown } | null }[] | null };
90	
91	export async function loadTransferCandidates(db: SupabaseClient, workspaceId: string) {
92	  const rows: TransferCandidate[] = [];
93	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
94	    const { data, error } = await db.from("transactions")
95	      .select("id, version, account_id, posted_on, amount_minor::text, currency_code, review_reasons, transaction_sources(source_transactions(original_row))")
96	      .eq("workspace_id", workspaceId).eq("status", "posted").eq("kind", "ordinary").is("transfer_id", null).is("refund_of_id", null)
97	      .order("posted_on", { ascending: false }).order("id").range(from, from + PAGE - 1);
98	    if (error) throw new Error(error.message);
99	    for (const row of (data ?? []) as unknown as Row[]) {
100	      const reviewReasons = row.review_reasons ?? [];
101	      if (reviewReasons.some(reason => reason !== "source_transfer")) continue;
102	      rows.push({ id: row.id, version: row.version, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor),
103	        currencyCode: row.currency_code, reviewReasons, ibans: [...new Set((row.transaction_sources ?? []).flatMap(source => sourceIbans(source.source_transactions?.original_row)))] });
104	    }
105	    if ((data ?? []).length < PAGE) break;
106	  }
107	  return rows;
108	}
109	
110	/** Every posted leg, whatever its review state, so a lone leg can see whether its other side exists. */

