1	"use client";
2	
3	import { createContext, useContext, useEffect, useRef, useState, type ReactNode } from "react";
4	import { useBusy } from "@/components/use-busy";
5	import { CategoryCombobox, resolveCategory } from "@/components/category-combobox";
6	import Link from "next/link";
7	import { useRouter } from "next/navigation";
8	import { ChevronRight, X } from "lucide-react";
9	import { RecurringCards } from "@/app/money/recurring/cards";
10	import { decideAgentProposals } from "@/app/ai/agents/actions";
11	import { displayFormat } from "@/lib/display-format";
12	import { categorizeGroups, loadUncategorizedGroups, type UncategorizedGroup } from "./home-review-actions";
13	import type { OpenProposal } from "@/lib/ai/open-proposals";
14	import type { HomeFinding } from "@/lib/ai/home-review";
15	
16	const primary = "min-h-9 rounded-lg bg-primary px-4 text-sm font-medium text-primary-foreground disabled:opacity-50";
17	const secondary = "min-h-9 rounded-lg border border-border px-4 text-sm hover:bg-muted disabled:opacity-50";
18	
19	/** A sheet tells its summary card when nothing is left, so the card goes away without waiting for Home to reload. */
20	const Cleared = createContext<(cleared: boolean) => void>(() => {});
21	
22	/** One line on Home for a whole kind of decision; Review opens the items in a sheet over the page. */
23	export function SummaryCard({ title, detail, children }: { title: string; detail: string; children: ReactNode }) {
24	  const dialog = useRef<HTMLDialogElement>(null);
25	  const [open, setOpen] = useState(false);
26	  const [cleared, setCleared] = useState(false);
27	  const router = useRouter();
28	  useEffect(() => { if (open) dialog.current?.showModal(); }, [open]);
29	  if (cleared && !open) return null;
30	  return <Cleared.Provider value={setCleared}><section aria-label={title} className="my-3 flex flex-wrap items-center gap-3 rounded-xl border border-ai-border bg-ai-soft p-4">
31	    <div className="min-w-0 flex-1"><p className="font-medium">{title}</p><p className="mt-0.5 text-sm text-muted-foreground">{detail}</p></div>
32	    <button type="button" aria-label={`Review: ${title}`} onClick={() => setOpen(true)} className={`${primary} inline-flex items-center gap-1`}>Review<ChevronRight className="size-4" aria-hidden="true" /></button>
33	    {/* Closing refreshes Home so the counts match what was decided. */}
34	    {open && <dialog ref={dialog} aria-label={title} onClose={() => { setOpen(false); router.refresh(); }}
35	      className="m-auto mb-0 max-h-[85dvh] w-full max-w-2xl overflow-y-auto rounded-t-2xl border border-border bg-background p-5 text-foreground backdrop:bg-black/40 sm:mb-auto sm:rounded-2xl">
36	      <div className="flex items-center gap-2"><h2 className="mr-auto font-display text-lg font-semibold">{title}</h2>
37	        <button type="button" onClick={() => dialog.current?.close()} aria-label="Close" className="rounded-lg p-2 hover:bg-muted"><X className="size-4" aria-hidden="true" /></button></div>
38	      {children}
39	    </dialog>}
40	  </section></Cleared.Provider>;
41	}
42	
43	/** Reports to the summary card whether every item in its sheet is decided. */
44	function useReportCleared(cleared: boolean) {
45	  const report = useContext(Cleared);
46	  useEffect(() => { report(cleared); }, [report, cleared]);
47	}
48	
49	function useDecide() {
50	  const [pending, start] = useBusy();
51	  const [error, setError] = useState<string>();
52	  const run = (work: () => Promise<string | void>) => start(async () => {
53	    setError(undefined);
54	    try { const failed = await work(); if (failed) setError(failed); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not save"); }
55	  });
56	  return { pending, error, run };
57	}
58	
59	/** Detected and chat-made recurring changes, one decision each: confirming opens the dialog to check amount, date and category. */
60	export function RecurringSheet({ proposals }: { proposals: OpenProposal[] }) {
61	  const [decided, setDecided] = useState<Set<string>>(new Set());
62	  const onDecided = (id: string, undone?: boolean) => setDecided(current => { const next = new Set(current); if (undone) next.delete(id); else next.add(id); return next; });
63	  const cleared = proposals.every(item => decided.has(item.id));
64	  useReportCleared(cleared);
65	  return <div>
66	    <p className="mt-2 text-sm text-muted-foreground">Confirmed payments go into your forecast. “Not recurring” is remembered.</p>
67	    <RecurringCards cards={proposals} onDecided={onDecided} />
