110	export function UncategorizedSheet({ total, locale = "en-GB" }: { total: number; locale?: string }) {
111	  const { date, money } = displayFormat(locale);
112	  const [data, setData] = useState<Awaited<ReturnType<typeof loadUncategorizedGroups>>>();
113	  const [chosen, setChosen] = useState<Record<string, string>>({});
114	  const [done, setDone] = useState<Record<string, string>>({});
115	  const [remember, setRemember] = useState(false);
116	  const { pending, error, run } = useDecide();
117	  // A failed load says so; treating it as empty would report everything as reviewed.
118	  const [failed, setFailed] = useState(false);
119	  const [attempt, setAttempt] = useState(0);
120	  useEffect(() => { loadUncategorizedGroups().then(setData, () => setFailed(true)); }, [attempt]);
121	  const shown = data?.groups.reduce((sum, group) => sum + group.count, 0) ?? 0;
122	  useReportCleared(!!data && data.total <= shown && data.groups.every(group => done[group.key] && done[group.key] !== "Skipped"));
123	  if (failed) return <p role="alert" className="mt-3 text-sm text-danger">Could not load these {total} transactions. <button type="button" onClick={() => { setFailed(false); setAttempt(count => count + 1); }} className="underline">Try again</button></p>;
124	  if (!data) return <p role="status" className="mt-3 text-sm text-muted-foreground">Grouping {total} transactions…</p>;
125	  // What is typed per group: the suggestion's name until the person changes it.
126	  const typed = (group: UncategorizedGroup) => chosen[group.key] ?? data.categories.find(category => category.id === group.suggested)?.name ?? "";
127	  const pick = (group: UncategorizedGroup) => resolveCategory(data.categories, typed(group), true);
128	  // Marked done at once; groups that fail to save are put back with the error.
129	  const apply = (groups: UncategorizedGroup[]) => run(async () => {
130	    const keys = groups.map(group => group.key);
131	    const restore = (failed: string[]) => setDone(current => Object.fromEntries(Object.entries(current).filter(([key]) => !failed.includes(key))));
132	    const outcome = (count: number) => `${count} categorized${remember ? ", future entries too" : ""}`;
133	    setDone(current => ({ ...current, ...Object.fromEntries(groups.map(group => [group.key, outcome(group.count)])) }));
134	    try {
135	      const { applied, error } = await categorizeGroups(groups.map(group => ({ rows: group.rows, key: group.key, ...(choice => choice && "id" in choice ? { categoryId: choice.id } : { newCategory: choice?.name })(pick(group)) })), remember);
136	      restore(keys.filter(key => !(key in applied)));
137	      setDone(current => ({ ...current, ...Object.fromEntries(Object.entries(applied).map(([key, count]) => [key, outcome(count)])) }));
138	      return error;
139	    } catch (cause) { restore(keys); throw cause; }
140	  });
141	  const open = data.groups.filter(group => !done[group.key]);
142	  const suggested = open.filter(group => { const choice = pick(group); return !!group.suggested && !!choice && "id" in choice && choice.id === group.suggested; });
143	  return <div>
144	    <div className="mt-2 flex flex-wrap items-center gap-2"><p className="mr-auto text-sm text-muted-foreground">Every batch can be undone.</p>
145	      {suggested.length > 0 && <button type="button" disabled={pending} className={primary} onClick={() => apply(suggested)}>Apply {suggested.length} suggested</button>}</div>
146	    <label className="mt-2 flex items-center gap-2 text-sm"><input type="checkbox" className="size-4" checked={remember} disabled={pending} onChange={event => setRemember(event.target.checked)} />Do the same for future entries</label>
147	    <p className="mt-1 text-xs text-muted-foreground">{remember ? "Applying also saves a rule, so future entries with the same description get this category." : "Applying changes only these transactions. Future entries stay uncategorized."}</p>
148	    {error && <p role="alert" className="mt-2 text-sm text-danger">{error}</p>}
149	    <ul className="mt-2 divide-y divide-border">{data.groups.map(group => <li key={group.key} className="flex flex-wrap items-center gap-2 py-3">
150	      <div className="w-full min-w-0"><p className="break-words text-sm font-medium">{group.label}</p>
151	        <details className="text-xs text-muted-foreground"><summary className="cursor-pointer hover:text-foreground">{group.count} {group.count === 1 ? "transaction" : "transactions"}{group.suggested ? " · suggestion preselected" : ""}</summary>
152	          <ul className="mt-1 divide-y divide-border rounded-lg border border-border bg-background">{group.recent.map(row => <li key={row.id}>
153	            <Link href={`/money/transactions?transaction=${row.id}`} className="flex items-baseline gap-3 px-3 py-1.5 hover:bg-muted">
154	              <span className="flex-1 font-mono">{date(row.date)}</span>
155	              <span className="shrink-0 font-mono text-foreground">{money(row.amountMinor, row.currency)}</span></Link></li>)}</ul>
156	          {group.count > group.recent.length && <p className="mt-1">…and {group.count - group.recent.length} more.</p>}
157	        </details></div>
158	      {done[group.key] ? <p role="status" className="text-sm">{done[group.key]}</p> : <>
159	        <CategoryCombobox label={`Category for ${group.label}`} options={data.categories} value={typed(group)} allowCreate placeholder="Type a category" disabled={pending}
160	          onChange={text => setChosen(current => ({ ...current, [group.key]: text }))} className="flex-1 sm:max-w-56" />
161	        <button type="button" disabled={pending || !pick(group)} className={primary} onClick={() => apply([group])}>Apply</button>
162	        <button type="button" disabled={pending} className={secondary} onClick={() => setDone(current => ({ ...current, [group.key]: "Skipped" }))}>Skip</button>
163	      </>}
164	    </li>)}</ul>
165	    {data.total > data.groups.reduce((sum, group) => sum + group.count, 0) && <p className="mt-3 text-xs text-muted-foreground">Showing the {data.groups.length} biggest groups. <Link href="/money/organization" className="underline">Sort the rest on Organize</Link></p>}
166	  </div>;
167	}
