111	async function loadLegs(db: SupabaseClient, workspaceId: string): Promise<Leg[]> {
112	  const legs: Leg[] = [];
113	  for (let from = 0; from < MAX_ROWS; from += PAGE) {
114	    const { data, error } = await db.from("transactions")
115	      .select("id, account_id, posted_on, amount_minor::text, currency_code")
116	      .eq("workspace_id", workspaceId).eq("status", "posted").order("id").range(from, from + PAGE - 1);
117	    if (error) throw new Error(error.message);
118	    for (const row of data ?? []) legs.push({ id: row.id, accountId: row.account_id, postedOn: row.posted_on, amountMinor: BigInt(row.amount_minor), currencyCode: row.currency_code });
119	    if ((data ?? []).length < PAGE) break;
120	  }
121	  return legs;
122	}
