124	/** Find and link transfers between the owner's accounts. The service role acts for the owner. */
125	export async function linkOwnTransfers(db: SupabaseClient, workspaceId: string) {
126	  const [own, rows, legs] = await Promise.all([loadOwnAccounts(db, workspaceId), loadTransferCandidates(db, workspaceId), loadLegs(db, workspaceId)]);
127	  const { pairs, single } = findOwnTransfers(rows, own, legs);
128	  const byId = new Map(rows.map(row => [row.id, row]));
129	  let linked = 0, marked = 0, skipped = 0;
130	  for (const pair of pairs) {
131	    const out = byId.get(pair.outId)!, into = byId.get(pair.inId)!;
132	    // The RPC rejects pairs it can't prove (e.g. a documented fee); those stay for manual review.
133	    const { error } = await db.rpc("link_transactions", { p_operation: "transfer", p_primary_id: out.id, p_expected_version: out.version,
134	      p_other_id: into.id, p_other_version: into.version, p_fx_rate_id: null, p_fees: [], p_request_id: randomUUID() });
135	    if (error) skipped++; else linked++;
136	  }
137	  for (const item of single) {
138	    const expectedVersion = byId.get(item.transactionId)!.version;
139	    const { error } = item.identifierId
140	      ? await db.rpc("mark_own_account_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_identifier_id: item.identifierId })
141	      : await db.rpc("mark_own_iban_transfer", { p_transaction_id: item.transactionId, p_expected_version: expectedVersion, p_iban: item.iban });
142	    if (error) skipped++; else marked++;
143	  }
144	  return { linked, marked, skipped };
145	}
