138	    pages(offset => db.from("transactions").select(columns).eq("workspace_id", workspace.id).eq("status", "posted").or("merchant_id.is.null,category_id.is.null").order("posted_on", { ascending: false }).order("id").range(offset, offset + 999)),
139	    db.from("transactions").select(columns).eq("workspace_id", workspace.id).eq("status", "posted").order("posted_on", { ascending: false }).order("id", { ascending: false }).limit(2000),
140	    db.from("correction_events").select("transaction_id").eq("workspace_id", workspace.id).eq("undone", false).limit(5000),
141	    db.from("organization_rules").select("id,version,description_key,merchant_id,category_id,approved_by,enabled").eq("workspace_id", workspace.id).order("description_key").limit(MAX_ORGANIZATION_RULES),
142	    names(db, workspace.id),
143	  ]);
144	  const corrected = new Set((checked(corrections) as { transaction_id: string }[]).map(row => row.transaction_id));
145	  // A loan's payout is recorded in Wealth, not spending to categorize.
