149	    kind: row.kind as OrganizationRow["kind"], reviewReasons: row.review_reasons ?? [], userCorrected: corrected.has(row.id) });
150	  const approved = (checked(rules) as { id: string; version: number; description_key: string; merchant_id: string | null; category_id: string | null; approved_by: string; enabled: boolean }[])
151	    .map(rule => organizationRuleSchema.parse({ id: rule.id, version: rule.version, descriptionKey: rule.description_key, merchantId: rule.merchant_id, categoryId: rule.category_id, approvedBy: rule.approved_by, enabled: rule.enabled }));
152	  const historyRows = (checked(history) as RawRow[]).map(toRow);
153	  await report(context, { type: "tool", text: `organization_rules + history: ${approved.length} rules, ${historyRows.length} earlier rows` });
