273	/** Registers the workflow, profiles the data and writes the lead's plan. Resumes keep finished tasks. */
274	export async function startRun(runId: string, workspaceId: string, workflowRunId: string): Promise<AgentId[][] | null> {
275	  const db = service();
276	  try { await activeRun(db, runId, workspaceId); } catch (error) { if (error instanceof RunInactive) return null; throw error; }
277	  checked(await db.from("agent_runs").update({ status: "running", workflow_run_id: workflowRunId, error: null, updated_at: new Date().toISOString() }).eq("id", runId).eq("workspace_id", workspaceId));
278	  const { workspace, settings, today } = await loadWorkspace(db, workspaceId);
279	  const existing = checked(await db.from("agent_tasks").select("agent, status").eq("run_id", runId).eq("workspace_id", workspaceId)) as { agent: AgentId; status: string }[];
280	  const lead = { db, runId, workspace, agent: "lead" as const };
281	  if (!existing.length) {
282	    checked(await db.from("agent_tasks").insert({ run_id: runId, workspace_id: workspaceId, agent: "lead", position: 0, status: "running", started_at: new Date().toISOString() }));
283	    await report(lead, { type: "step", text: "Profiling your data" });
284	    const canRead = settings.ai_data_scopes.includes("transactions");
285	    const [count, unorganized, oldest] = canRead ? await Promise.all([
286	      db.from("transactions").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "posted"),
287	      db.from("transactions").select("id", { count: "exact", head: true }).eq("workspace_id", workspaceId).eq("status", "posted").or("merchant_id.is.null,category_id.is.null"),
288	      db.from("transactions").select("posted_on").eq("workspace_id", workspaceId).eq("status", "posted").order("posted_on").limit(1).maybeSingle(),
289	    ]) : [{ count: 0, error: null }, { count: 0, error: null }, { data: null, error: null }];
290	    for (const result of [count, unorganized, oldest]) if (result.error) throw new Error(result.error.message);
291	    const first = (oldest.data as { posted_on: string } | null)?.posted_on;
292	    const months = first ? (Number(today.slice(0, 4)) - Number(first.slice(0, 4))) * 12 + Number(today.slice(5, 7)) - Number(first.slice(5, 7)) : 0;
293	    let modelStatus = "disabled";
294	    if (await aiConfigured()) modelStatus = await modelForSettings(settings, "agents").then(() => "available", () => "unavailable");
295	    const plan = planRun({ transactions: count.count ?? 0, unorganized: unorganized.count ?? 0, months, scopes: settings.ai_data_scopes });
296	    checked(await db.from("agent_runs").update({ plan, model_status: modelStatus }).eq("id", runId).eq("workspace_id", workspaceId));
297	    checked(await db.from("agent_tasks").insert(plan.map((task, index) => ({ run_id: runId, workspace_id: workspaceId, agent: task.agent, position: index + 1,
298	      status: task.status, step: task.reason, ...(task.status === "skipped" ? { summary: task.reason, finished_at: new Date().toISOString() } : {}) }))));
299	    const running = plan.filter(task => task.status === "pending");
300	    await report(lead, { type: "step", text: `Assigned ${running.length} agents in ${new Set(running.map(task => task.wave)).size} waves` }, { summary: `Planned ${running.length} of ${plan.length} agents` });
301	    await report(lead, { type: "note", text: modelStatus === "available" ? "Model ready; at most 6 model calls for this run" : "No model available; every agent runs deterministically" });
302	  } else await report(lead, { type: "step", text: "Resuming: finished agents keep their results" }, { status: "running" });
303	  const tasks = checked(await db.from("agent_tasks").select("agent, status").eq("run_id", runId).eq("workspace_id", workspaceId)) as { agent: AgentId; status: string }[];
304	  const pending = new Set(tasks.filter(task => task.status === "pending" && task.agent !== "lead").map(task => task.agent));
305	  return WAVES.map(wave => wave.filter(agent => pending.has(agent)));
306	}
