308	/** Runs one agent. Agent failures stay inside the task so the rest of the team continues. */
309	export async function runAgent(runId: string, workspaceId: string, agent: Exclude<AgentId, "lead">): Promise<string> {
310	  const db = service();
311	  try { await activeRun(db, runId, workspaceId); } catch (error) { if (error instanceof RunInactive) return "canceled"; throw error; }
312	  const task = checked(await db.from("agent_tasks").select("status").eq("run_id", runId).eq("workspace_id", workspaceId).eq("agent", agent).single()) as { status: string };
313	  if (task.status !== "pending" && task.status !== "running") return task.status;
314	  const { workspace, settings, today } = await loadWorkspace(db, workspaceId);
315	  const context: Context = { db, runId, workspace, settings, today, agent };
316	  checked(await db.from("agent_tasks").update({ status: "running", started_at: new Date().toISOString() }).eq("run_id", runId).eq("workspace_id", workspaceId).eq("agent", agent));
317	  try {
318	    requireAiScope(settings, ...AGENTS[agent].scopes);
319	    const { proposals: found, summary } = await RUNNERS[agent](context);
320	    // A finding is raised once: an earlier run's open or decided one stands, so "It's fine" on Home sticks.
321	    const findingKeys = found.filter(item => item.kind === "finding").map(item => item.conflictKey);
322	    const earlier = findingKeys.length ? new Set((checked(await db.from("agent_proposals").select("conflict_key").eq("workspace_id", workspaceId).eq("kind", "finding")
323	      .neq("run_id", runId).in("conflict_key", findingKeys)) as { conflict_key: string }[]).map(row => row.conflict_key)) : new Set<string>();
324	    const proposals = found.filter(item => item.kind !== "finding" || !earlier.has(item.conflictKey));
325	    await activeRun(db, runId, workspaceId);
326	    if (proposals.length) checked(await db.from("agent_proposals").upsert(proposals.map(item => ({ run_id: runId, workspace_id: workspaceId, agent: item.agent, kind: item.kind,
327	      conflict_key: item.conflictKey, title: item.title.slice(0, 200), detail: item.detail, evidence: item.evidence, payload: item.payload, confidence: item.confidence, notes: item.notes })),
328	    { onConflict: "run_id,conflict_key", ignoreDuplicates: true }));
329	    for (const item of proposals.slice(0, 5)) await report(context, { type: "finding", text: item.title });
330	    await report(context, { type: "step", text: "Done" }, { status: "done", summary, finished_at: new Date().toISOString() });
331	    return "done";
332	  } catch (error) {
333	    const canceled = error instanceof RunInactive;
334	    await report(context, { type: "note", text: canceled ? "Stopped" : `Failed: ${error instanceof Error ? error.message : String(error)}` },
335	      { status: canceled ? "canceled" : "failed", finished_at: new Date().toISOString() });
336	    return canceled ? "canceled" : "failed";
337	  }
338	}
