340	/** The lead merges every agent's proposals and resolves conflicts between them. */
341	export async function mergeRun(runId: string, workspaceId: string) {
342	  const db = service();
343	  try { await activeRun(db, runId, workspaceId); } catch (error) { if (error instanceof RunInactive) return false; throw error; }
344	  const { workspace } = await loadWorkspace(db, workspaceId);
345	  const lead = { db, runId, workspace, agent: "lead" as const };
346	  await report(lead, { type: "step", text: "Merging results and resolving conflicts" });
347	  const before = await runProposals(db, runId, workspaceId);
348	  const { proposals, resolutions } = mergeProposals(before);
349	  const kept = new Set(proposals.map(item => item.conflictKey));
350	  const dropped = before.filter(item => !kept.has(item.conflictKey)).map(item => item.conflictKey);
351	  if (dropped.length) checked(await db.from("agent_proposals").delete().eq("run_id", runId).eq("workspace_id", workspaceId).eq("status", "proposed").in("conflict_key", dropped));
352	  for (const item of proposals) {
353	    const original = before.find(other => other.conflictKey === item.conflictKey);
354	    if (original && (original.confidence !== item.confidence || original.notes.length !== item.notes.length))
355	      checked(await db.from("agent_proposals").update({ confidence: item.confidence, notes: item.notes }).eq("run_id", runId).eq("workspace_id", workspaceId).eq("conflict_key", item.conflictKey));
356	  }
357	  for (const text of resolutions.slice(0, 10)) await report(lead, { type: "note", text });
358	  // Repayments of money lent or borrowed wait for review on Home and here; a failed lookup never fails the run.
359	  try { for (const found of await proposeRepayments({ supabase: db, workspace })) await report(lead, { type: "finding", text: found.title }); }
360	  catch (cause) { await report(lead, { type: "note", text: `Could not check loan repayments: ${cause instanceof Error ? cause.message : String(cause)}` }); }
361	  await report(lead, { type: "step", text: `${proposals.length} proposals ready for review` }, { summary: `Merged ${before.length} results into ${proposals.length} proposals; ${resolutions.length} conflicts resolved` });
362	  return true;
363	}
