1	import type { requireWorkspace } from "@/lib/auth";
2	import { loadOrganizationSuggestions } from "@/lib/import/organization-loader";
3	import { payloadSchemas, type ProposalKind } from "@/lib/ai/agent-team";
4	import { calendarDate } from "@/lib/finance/calendar";
5	import { iouCreateSchema, iouRecord, iouSettleSchema, parseIouName, settledRecord } from "@/lib/finance/iou";
6	import { applyTransactionProposal } from "@/lib/ai/transaction-proposals";
7	import { applyBalanceProposal } from "@/lib/ai/balance-proposals";
8	import { applyRecurringProposal, dismissRecurringProposal } from "@/lib/ai/recurring-proposals";
9	import type { ScheduleFields } from "@/app/money/recurring/schedules";
10	import { applyScalableProposal, OrderOutcomeUnknown, TRADE_KINDS } from "@/lib/scalable/orders";
11	import { withScalable } from "@/lib/scalable/server";
12	
13	// Accepting a proposal calls the SAME audited RPCs a person uses by hand, as
14	// the signed-in owner (auth.uid()), so corrections, batches and Undo stay intact.
15	type Context = Awaited<ReturnType<typeof requireWorkspace>>;
16	export type StoredProposal = { id: string; kind: ProposalKind | "iou_create" | "iou_settle" | "transaction_create" | "balance_set" | "recurring_edit" | "scalable_order" | "scalable_cancel"; payload: unknown };
17	/** Choices made on the card itself: the account a chat expense is paid from, or what the person set when confirming a recurring payment. */
18	export type DecideOptions = { accountId?: string; recurring?: Partial<ScheduleFields> };
19	export type Applied = { href: string; undo?: string; [key: string]: unknown };
20	
21	export async function applyProposal(context: Context, proposal: StoredProposal, options: DecideOptions = {}): Promise<Applied> {
22	  const { supabase, workspace } = context;
23	  switch (proposal.kind) {
24	    case "categorize": {
25	      const payload = payloadSchemas.categorize.parse(proposal.payload);
26	      // Same guard as a manual organization review: corrections and complete rows take precedence.
27	      const current = await loadOrganizationSuggestions(supabase, workspace.id, payload.rows);
28	      if (current.proposals.length !== payload.rows.length) throw new Error("Some rows were corrected or organized since the agent ran");
29	      const evidence = [...new Map(current.proposals.flatMap(item => item.evidence).map(row => [row.id, row])).values()];
30	      const created = await supabase.rpc("create_organization_review", { p_rows: payload.rows, p_patch: payload.patch, p_merchant_name: payload.merchantName,
31	        p_rule_key: payload.ruleKey, p_evidence: evidence, p_request_id: proposal.id });
32	      if (created.error) throw new Error(created.error.message);
33	      const reviewId = String(created.data.id);
34	      const applied = await supabase.rpc("apply_organization_review", { p_review_id: reviewId, p_save_rule: payload.ruleKey !== null });
35	      if (applied.error) throw new Error(applied.error.message);
36	      return { reviewId, href: `/money/organization?review=${reviewId}`, undo: "Undo from the organization review" };
37	    }
38	    case "recurring": {
39	      const payload = payloadSchemas.recurring.parse(proposal.payload);
40	      const { error } = await supabase.rpc("review_recurring_series_versions", { p_decision: "confirmed", p_account_id: payload.accountId, p_label: payload.label,
41	        p_cadence: payload.cadence, p_currency_code: payload.currencyCode, p_evidence: payload.evidence, p_run_anchor_id: payload.runAnchorId, p_evidence_limited: payload.evidenceLimited });
42	      if (error) throw new Error(error.message);
43	      return { href: "/money/recurring", undo: "Choose “Not recurring” on the Recurring page" };
44	    }
45	    case "budget": {
46	      const payload = payloadSchemas.budget.parse(proposal.payload);
47	      const category = await supabase.from("categories").select("id").eq("workspace_id", workspace.id).eq("id", payload.categoryId).maybeSingle();
48	      if (category.error || !category.data) throw new Error("Category not found");
49	      // Same insert as Plan → Spending limits; a target only, never touches balances or goals.
50	      const { error } = await supabase.from("spending_plans").insert({ workspace_id: workspace.id, category_id: payload.categoryId, currency_code: payload.currencyCode,
51	        limit_minor: payload.limitMinor, enabled: true, updated_at: new Date().toISOString() });
52	      if (error?.code === "23505") throw new Error("A limit already exists for this category and currency");
53	      if (error) throw new Error(error.message);
54	      return { href: "/plan/spending", undo: "Turn the limit off in Plan → Spending" };
55	    }
56	    case "iou_create": {
57	      // The proposal id is both the new item's id and the request id, so accepting twice cannot duplicate it.
58	      const record = iouRecord(iouCreateSchema.parse(proposal.payload));
59	      const { error } = await supabase.rpc("edit_wealth_item", { p_id: proposal.id, p_expected_version: 0, p_record: record, p_remove: false, p_request_id: proposal.id });
60	      if (error) throw new Error(error.message);
61	      return { href: "/money/wealth", undo: "Undo from the Wealth history" };
62	    }
63	    case "iou_settle": {
64	      const payload = iouSettleSchema.parse(proposal.payload);
65	      const [item, transaction] = await Promise.all([
66	        supabase.from("wealth_items").select("id, kind, name, currency_code, amount_minor::text, as_of, version, removed_at, linked_account_id, annual_rate_text, monthly_payment_minor::text")
67	          .eq("workspace_id", workspace.id).eq("id", payload.itemId).is("removed_at", null).maybeSingle(),
68	        supabase.from("transactions").select("id, amount_minor::text, currency_code").eq("workspace_id", workspace.id).eq("id", payload.transactionId).maybeSingle(),
69	      ]);
70	      if (item.error || !item.data || !parseIouName(item.data.name)) throw new Error("This loan changed or was removed since the repayment was found");
71	      const paid = transaction.data ? BigInt(transaction.data.amount_minor) : 0n;
72	      const lent = item.data.kind === "asset";
73	      if (transaction.data?.currency_code !== item.data.currency_code || (lent ? paid <= 0n : paid >= 0n) || BigInt(payload.appliedMinor) > (paid < 0n ? -paid : paid))
74	        throw new Error("The transaction no longer matches this repayment");
75	      const next = settledRecord(item.data, payload.appliedMinor, calendarDate(new Date(), workspace.timezone));
76	      const { error } = await supabase.rpc("edit_wealth_item", { p_id: item.data.id, p_expected_version: item.data.version, p_record: next ?? {}, p_remove: next === null, p_request_id: proposal.id });
77	      if (error) throw new Error(error.message);
78	      return { href: "/money/wealth", undo: "Undo from the Wealth history" };
79	    }
80	    case "transaction_create":
81	      return applyTransactionProposal(context, proposal.id, proposal.payload, options.accountId);
82	    case "balance_set":
83	      return applyBalanceProposal(context, proposal.id, proposal.payload);
84	    case "recurring_edit":
85	      return applyRecurringProposal(context, proposal.id, proposal.payload, options.recurring);
86	    // The only path that places or cancels a Scalable order: the owner tapped the card.
87	    case "scalable_order":
88	    case "scalable_cancel":
89	      return applyScalableProposal(proposal.kind, proposal.payload, connectionId => work => withScalable(connectionId, workspace.id, work));
90	    case "finding":
91	      payloadSchemas.finding.parse(proposal.payload);
92	      return { href: "/money/transactions", acknowledged: true };
93	  }
94	}
