96	/**
97	 * A message a person can act on. When the database or its proxy is unreachable the client hands back an HTML error page
98	 * (a Cloudflare 5xx screen), which is no use on a card.
99	 */
100	export function readableError(cause: unknown) {
101	  const message = cause instanceof Error || (typeof cause === "object" && cause && "message" in cause) ? String((cause as { message: unknown }).message) : String(cause);
102	  return /<(!doctype|html|head|body)\b/i.test(message) || /cloudflare/i.test(message) ? "The database did not answer. Nothing was saved; try again in a moment." : message.slice(0, 500);
103	}
