105	/** Claims each proposal once, applies it, and records the outcome. Rejecting only changes a dismissed recurring pattern's review state. */
106	export async function decideProposals(context: Context, ids: string[], decision: "accept" | "reject", options: DecideOptions = {}) {
107	  const { supabase, workspace } = context;
108	  const outcomes: { id: string; status: string; error?: string }[] = [];
109	  for (const id of ids) {
110	    const now = new Date().toISOString();
111	    if (decision === "reject") {
112	      // A dismissed recurring pattern is remembered on the series first; if that fails the card stays open to try again.
113	      // Dismissing a price change only keeps the old amount.
114	      const open = await supabase.from("agent_proposals").select("conflict_key, payload").eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"]).maybeSingle();
115	      const dismissed = open.data && String(open.data.conflict_key).startsWith("recurring_new:")
116	        ? await dismissRecurringProposal(context, id, open.data.payload).then(() => undefined, (cause: unknown) => readableError(cause)) : undefined;
117	      if (open.error || dismissed) { outcomes.push({ id, status: "failed", error: open.error ? readableError(open.error) : dismissed }); continue; }
118	      const { data, error } = await supabase.from("agent_proposals").update({ status: "rejected", decided_at: now }).eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"])
119	        .select("id").maybeSingle();
120	      outcomes.push({ id, status: error ? "failed" : data ? "rejected" : "unchanged", ...(error ? { error: readableError(error) } : {}) });
121	      continue;
122	    }
123	    let claiming = supabase.from("agent_proposals").update({ status: "applying", decided_at: now }).eq("id", id).eq("workspace_id", workspace.id).in("status", ["proposed", "failed"]);
124	    // Each Scalable order is confirmed on its own card, never by an "accept all".
125	    if (ids.length > 1) claiming = claiming.not("kind", "in", `(${TRADE_KINDS.join(",")})`);
126	    const claim = await claiming.select("id, kind, payload").maybeSingle();
127	    if (claim.error || !claim.data) { outcomes.push({ id, status: "unchanged", ...(claim.error ? { error: claim.error.message } : {}) }); continue; }
128	    let result: Applied;
129	    try { result = await applyProposal(context, claim.data as StoredProposal, options); }
130	    catch (cause) {
131	      const message = readableError(cause);
132	      // A trade Scalable may have carried out stays "applying", so the card can never send it twice.
133	      if (cause instanceof OrderOutcomeUnknown) {
134	        await supabase.from("agent_proposals").update({ result: { error: message, unknown: true } }).eq("id", id).eq("workspace_id", workspace.id).eq("status", "applying");
135	        outcomes.push({ id, status: "unknown", error: message });
136	        continue;
137	      }
138	      await supabase.from("agent_proposals").update({ status: "failed", result: { error: message } }).eq("id", id).eq("workspace_id", workspace.id).eq("status", "applying");
139	      outcomes.push({ id, status: "failed", error: message });
140	      continue;
141	    }
142	    const saved = await supabase.from("agent_proposals").update({ status: "accepted", result, decided_at: new Date().toISOString() }).eq("id", id).eq("workspace_id", workspace.id).eq("status", "applying");
143	    outcomes.push({ id, status: "accepted", ...(saved.error ? { error: `Applied, but the review record was not updated: ${saved.error.message}` } : {}) });
144	  }
145	  return outcomes;
146	}
